#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <libgen.h>
#include <php_globals.h>
#include "php_main.h"

long get_device_id_from_symlink(char *link) {
    char *resolved_link = strdup(link);
    if (!resolved_link) {
        php_error_docref(NULL, E_WARNING, "Failed to duplicate link path");
        return -1;
    }

    char *dir_name = dirname(resolved_link);
    if (!dir_name) {
        php_error_docref(NULL, E_WARNING, "Failed to derive directory name from link path");
        free(resolved_link);
        return -1;
    }

    if (!PG(open_basedir) || php_check_open_basedir(dir_name, 0, NULL)) {
        struct stat file_stat;
        if (VCWD_STAT(link, &file_stat) == 0) {
            free(resolved_link);
            return file_stat.st_dev;
        }

        php_error_docref(NULL, E_WARNING, "Failed to retrieve file status");
        free(resolved_link);
        return -1;
    }

    free(resolved_link);
    return -1;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

long get_device_id_from_symlink(const char *link) {
    char *resolved_link = NULL;
    struct stat file_stat;
    long device_id = -1;

    resolved_link = strdup(link);
    if (!resolved_link) {
        return -1;
    }

    if (VCWD_STAT(resolved_link, &file_stat) != 0) {
        free(resolved_link);
        return -1;
    }

    device_id = (long) file_stat.st_dev;
    free(resolved_link);
    return device_id;
}

#include <stdio.h>
