long get_file_device_id_from_symlink(char* link) {
    char* link_path = strdup(link);
    if (!link_path) {
        return -1;
    }

    char* dir_name = dirname(link_path);
    // Assume check_basedir is a function defined in the codebase
    if (!check_basedir(dir_name, 0)) {
        free(link_path);
        return -1;
    }

    struct stat file_stat;
    if (VCWD_STAT(link, &file_stat) == -1) {
        free(link_path);
        return -1;
    }

    free(link_path);
    return (long)file_stat.st_dev;
}

