long get_device_id_from_symlink(const char* link) {
    char* path_copy = strdup(link);
    if (!path_copy) {
        return -1;
    }

    char* dir_name = dirname(path_copy);
    if (!dir_name || access(dir_name, F_OK) != 0) {
        free(path_copy);
        return -1;
    }

    struct stat file_stat;
    if (VCWD_STAT(link, &file_stat) != 0) {
        free(path_copy);
        return -1;
    }

    free(path_copy);
    return (long)file_stat.st_dev;
}

